package stream

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// TestReproTailSegmentsPlayable is the DIAG-REPRO artifact of the
// fix-episode-playback /fix pre-step (wf-debugger, 2026-10-11). It pins the
// player's contract on the head+tail pack lane against a LONG fixture
// (30 s: head 5 s + tail 25 s → ~12 tail segments, i.e. MORE than ffmpeg 7.1.1's
// default hls_list_size of 5 — the existing 12 s fixtures never cross the
// window, which is why the defect ships invisibly). Two assertions per
// published media playlist:
//
//  1. REACHABILITY — every referenced URI (segments and EXT-X-MAP) must
//     resolve to an existing file relative to the playlist's OWN directory
//     (how hls.js resolves relative playlist URIs).
//  2. TAIL COVERAGE — the playlist must list every tail segment ffmpeg wrote
//     under the build's t/ tree; a playlist that omits published segments
//     makes that content unreachable and misrepresents the duration.
//
// Failure modes observed against the current code (real library evidence,
// data/streams/itm_3_4abdae6f23167012 and itm_3_da5839903ded1974):
//   - the tail-phase ffmpeg run emits a 5-entry sliding-window playlist
//     (no -hls_list_size 0 and no EVENT playlist type on the tail), so the
//     merged playlist lists only the LAST ~5 tail segments;
//   - rendition builds additionally prefix tail URIs "t/rendN/..." into
//     rendN/index.m3u8, which resolves to rendN/t/rendN/... while moveTree
//     publishes the files at <build>/t/rendN/... — those refs 404 for the
//     player and end playback in the fatal banner.
//
// This test is EXPECTED TO FAIL until the fix lands; it is the first probe
// the fix change anchors on.
func TestReproTailSegmentsPlayable(t *testing.T) {
	ctx := context.Background()

	// playlistRefs returns the referenced URIs of a media playlist: every
	// non-tag line (segment URIs) plus every EXT-X-MAP URI="..." attribute.
	playlistRefs := func(t *testing.T, pl string) []string {
		t.Helper()
		var refs []string
		for _, line := range strings.Split(pl, "\n") {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") {
				if strings.HasPrefix(line, "#EXT-X-MAP") {
					if i := strings.Index(line, `URI="`); i >= 0 {
						rest := line[i+len(`URI="`):]
						if j := strings.Index(rest, `"`); j >= 0 {
							refs = append(refs, rest[:j])
						}
					}
				}
				continue
			}
			refs = append(refs, line)
		}
		return refs
	}

	// assertReachable fails unless every ref resolves to an existing file
	// relative to the playlist's own directory (the hls.js contract).
	assertReachable := func(t *testing.T, playlistPath string) {
		t.Helper()
		b, err := os.ReadFile(playlistPath)
		if err != nil {
			t.Fatalf("published playlist %s: %v", playlistPath, err)
		}
		base := filepath.Dir(playlistPath)
		for _, ref := range playlistRefs(t, string(b)) {
			if _, err := os.Stat(filepath.Join(base, ref)); err != nil {
				t.Errorf("playlist %s references %q: not found relative to the playlist dir (player 404)", playlistPath, ref)
			}
		}
	}

	// assertTailCoverage fails unless the playlist lists every tail segment
	// present under the build's tail tree (root t/ for single-variant,
	// t/rendN/ per rendition playlist).
	assertTailCoverage := func(t *testing.T, playlistPath, tailDir string) {
		t.Helper()
		b, err := os.ReadFile(playlistPath)
		if err != nil {
			t.Fatalf("published playlist %s: %v", playlistPath, err)
		}
		entries, err := os.ReadDir(tailDir)
		if err != nil {
			t.Fatalf("tail dir %s: %v", tailDir, err)
		}
		onDisk := 0
		for _, e := range entries {
			if !e.IsDir() && strings.HasPrefix(e.Name(), "seg-") {
				onDisk++
			}
		}
		listed := 0
		for _, ref := range playlistRefs(t, string(b)) {
			if strings.Contains(ref, "/seg-") || strings.HasPrefix(ref, "seg-") {
				if strings.HasPrefix(filepath.Base(ref), "seg-") && strings.Contains(ref, "/") {
					listed++ // tail refs are the ones carrying a directory prefix
				}
			}
		}
		if listed != onDisk {
			t.Errorf("playlist %s lists %d tail segments but %d were published under %s: the windowed tail playlist dropped %d segment(s); the merged playlist misrepresents the build",
				playlistPath, listed, onDisk, tailDir, onDisk-listed)
		}
	}

	t.Run("single_variant_full_tail_reachable", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 30*time.Second) // head 5 s + tail 25 s
		s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second)

		build, err := s.Pack(ctx, "repro1", fixture, map[string]any{"format": map[string]any{"duration": "30.0"}}, nil)
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		buildDir := filepath.Join(s.Root, "repro1", build.Nonce)
		assertReachable(t, filepath.Join(buildDir, "index.m3u8"))
		assertTailCoverage(t, filepath.Join(buildDir, "index.m3u8"), filepath.Join(buildDir, "t"))
	})

	t.Run("rendition_variants_full_tail_reachable", func(t *testing.T) {
		dir := t.TempDir()
		fixture := makeFixture(t, dir, 30*time.Second)
		dub := makeVoiceover(t, dir, "rus.mka", 600, 30*time.Second)
		s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second)

		build, err := s.Pack(ctx, "repro2", fixture, map[string]any{"format": map[string]any{"duration": "30.0"}}, []string{dub})
		if err != nil {
			t.Fatalf("Pack: %v", err)
		}
		buildDir := filepath.Join(s.Root, "repro2", build.Nonce)
		for _, rend := range []string{"rend0", "rend1", "rend2"} {
			plPath := filepath.Join(buildDir, rend, "index.m3u8")
			assertReachable(t, plPath)
			assertTailCoverage(t, plPath, filepath.Join(buildDir, "t", rend))
		}
	})
}
